    CONSTRAINT "inventory_inventory_stock_pkey" PRIMARY KEY ("stock_id"),
    CONSTRAINT "inventory_inventory_stock_tenant_key" UNIQUE ("school_id", "stock_id"),
    CONSTRAINT "inventory_inventory_stock_uq1" UNIQUE ("school_id", "item_catalog_id", "location_id")
);

CREATE TABLE "inventory"."asset_item" (
    "school_id" BIGINT NOT NULL,
    "asset_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_catalog_id" BIGINT NOT NULL,
    "barcode_id" TEXT,
    "purchase_date" DATE,
    "purchase_cost" NUMERIC(14,2),
    "vendor_id" BIGINT,
    "grn_line_id" BIGINT,
    "warranty_until" DATE,
    "amc_until" DATE,
    "status" TEXT NOT NULL DEFAULT 'IN_STORE' CHECK ("status" IN ('IN_STORE', 'ASSIGNED', 'IN_REPAIR', 'LOST', 'DISPOSED')),
    "assigned_location_id" BIGINT,
    "assigned_user_id" BIGINT,
    "assigned_student_id" BIGINT,
    "depreciation_method" TEXT,
    "useful_life_months" INTEGER,
    "disposed_on" DATE,
    CONSTRAINT "inventory_asset_item_pkey" PRIMARY KEY ("asset_id"),
    CONSTRAINT "inventory_asset_item_tenant_key" UNIQUE ("school_id", "asset_id"),
    CONSTRAINT "inventory_asset_item_barcode_id_key" UNIQUE ("school_id", "barcode_id")
);

CREATE TABLE "inventory"."inventory_transaction" (
    "school_id" BIGINT NOT NULL,
    "transaction_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_catalog_id" BIGINT NOT NULL,
    "asset_id" BIGINT,
    "issued_by_user_id" BIGINT,
    "issued_to_user_id" BIGINT,
    "txn_type" TEXT NOT NULL CHECK ("txn_type" IN ('RECEIPT', 'ISSUE', 'RETURN', 'TRANSFER', 'CONSUMPTION', 'ADJUSTMENT', 'WRITE_OFF')),
    "quantity" NUMERIC(14,2) NOT NULL,
    "unit_cost" NUMERIC(14,2),
    "from_location_id" BIGINT,
    "to_location_id" BIGINT,
    "issued_to_student_id" BIGINT,
    "issued_to_department_id" BIGINT,
    "cost_centre" TEXT,
    "reference_kind" TEXT,
    "reference_id" BIGINT,
    "batch_no" TEXT,
    "txn_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "note" TEXT,
    CONSTRAINT "inventory_inventory_transaction_pkey" PRIMARY KEY ("transaction_id"),
    CONSTRAINT "inventory_inventory_transaction_tenant_key" UNIQUE ("school_id", "transaction_id")
);

-- ---------------------------------------------------------------------------
