-- ---------------------------------------------------------------------------

CREATE TABLE "library"."library_book" (
    "school_id" BIGINT NOT NULL,
    "book_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "isbn" TEXT,
    "title" TEXT NOT NULL,
    "author" TEXT,
    "publisher" TEXT,
    "edition" TEXT,
    CONSTRAINT "library_library_book_pkey" PRIMARY KEY ("book_id"),
    CONSTRAINT "library_library_book_tenant_key" UNIQUE ("school_id", "book_id"),
    CONSTRAINT "library_library_book_isbn_key" UNIQUE ("school_id", "isbn")
);

CREATE TABLE "library"."book_copy" (
    "school_id" BIGINT NOT NULL,
    "copy_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "book_id" BIGINT NOT NULL,
    "location_id" BIGINT,
    "barcode" TEXT NOT NULL,
    CONSTRAINT "library_book_copy_pkey" PRIMARY KEY ("copy_id"),
    CONSTRAINT "library_book_copy_tenant_key" UNIQUE ("school_id", "copy_id"),
    CONSTRAINT "library_book_copy_barcode_key" UNIQUE ("school_id", "barcode")
);

CREATE TABLE "library"."library_borrowing" (
    "school_id" BIGINT NOT NULL,
    "borrowing_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "copy_id" BIGINT NOT NULL,
    "borrower_student_id" BIGINT,
    "borrower_user_id" BIGINT,
    "issued_by_user_id" BIGINT,
    "issued_on" DATE NOT NULL,
    "due_on" DATE,
    "returned_on" DATE,
    "fine_fee_id" BIGINT,
    CONSTRAINT "library_library_borrowing_pkey" PRIMARY KEY ("borrowing_id"),
    CONSTRAINT "library_library_borrowing_tenant_key" UNIQUE ("school_id", "borrowing_id")
);

-- ---------------------------------------------------------------------------
-- calendar
-- ---------------------------------------------------------------------------

CREATE TABLE "calendar"."event" (
    "school_id" BIGINT NOT NULL,
    "event_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "academic_year_id" BIGINT,
    "event_type" TEXT NOT NULL CHECK ("event_type" IN ('HOLIDAY', 'VACATION', 'EXAM', 'PTM', 'EVENT', 'WORKING_DAY', 'HOSTEL_VISITING_DAY')),
    "title" TEXT NOT NULL,
    "start_date" DATE NOT NULL,
    "end_date" DATE,
    "applies_to" TEXT DEFAULT 'ALL' CHECK ("applies_to" IN ('ALL', 'PROGRAM', 'SECTION', 'HOSTEL', 'STAFF')),
    "program_id" BIGINT,
    "class_section_id" BIGINT,
    "hostel_id" BIGINT,
    "is_holiday" BOOLEAN DEFAULT false,
    "created_by_user_id" BIGINT,
    CONSTRAINT "calendar_event_pkey" PRIMARY KEY ("event_id"),
    CONSTRAINT "calendar_event_tenant_key" UNIQUE ("school_id", "event_id")
);

-- ---------------------------------------------------------------------------
-- admissions
-- ---------------------------------------------------------------------------

CREATE TABLE "admissions"."seat_plan" (
    "school_id" BIGINT NOT NULL,
    "seat_plan_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "academic_year_id" BIGINT NOT NULL,
    "program_id" BIGINT NOT NULL,
    "total_seats" INTEGER,
    "rte_seats" INTEGER,
    "management_seats" INTEGER,
    "hostel_seats" INTEGER,
    CONSTRAINT "admissions_seat_plan_pkey" PRIMARY KEY ("seat_plan_id"),
    CONSTRAINT "admissions_seat_plan_tenant_key" UNIQUE ("school_id", "seat_plan_id"),
    CONSTRAINT "admissions_seat_plan_uq1" UNIQUE ("school_id", "academic_year_id", "program_id")
);

CREATE TABLE "admissions"."enquiry" (
    "school_id" BIGINT NOT NULL,
    "enquiry_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "academic_year_id" BIGINT,
    "program_id" BIGINT,
    "child_name" TEXT NOT NULL,
    "child_dob" DATE,
    "guardian_name" TEXT,
    "phone" TEXT NOT NULL,
    "email" TEXT,
    "source" TEXT CHECK ("source" IN ('WALK_IN', 'WEBSITE', 'PHONE', 'WHATSAPP', 'SOCIAL', 'REFERRAL', 'CAMPAIGN', 'EVENT')),
    "campaign" TEXT,
    "stage" TEXT NOT NULL CHECK ("stage" IN ('NEW', 'CONTACTED', 'VISIT_SCHEDULED', 'VISITED', 'APPLIED', 'LOST')),
    "owner_user_id" BIGINT,
    "next_follow_up_at" TIMESTAMPTZ,
    "lost_reason" TEXT,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "admissions_enquiry_pkey" PRIMARY KEY ("enquiry_id"),
    CONSTRAINT "admissions_enquiry_tenant_key" UNIQUE ("school_id", "enquiry_id")
);

CREATE TABLE "admissions"."enquiry_follow_up" (
    "school_id" BIGINT NOT NULL,
    "follow_up_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "enquiry_id" BIGINT NOT NULL,
    "channel" TEXT CHECK ("channel" IN ('CALL', 'WHATSAPP', 'EMAIL', 'VISIT')),
    "outcome" TEXT,
    "note" TEXT,
    "done_by_user_id" BIGINT,
    "done_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "admissions_enquiry_follow_up_pkey" PRIMARY KEY ("follow_up_id"),
    CONSTRAINT "admissions_enquiry_follow_up_tenant_key" UNIQUE ("school_id", "follow_up_id")
);

CREATE TABLE "admissions"."application" (
    "school_id" BIGINT NOT NULL,
    "application_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "enquiry_id" BIGINT,
    "academic_year_id" BIGINT,
    "program_id" BIGINT,
    "application_number" TEXT NOT NULL,
    "form_data" JSONB,
    "residency_requested" TEXT CHECK ("residency_requested" IN ('DAY_SCHOLAR', 'HOSTELLER')),
    "transport_requested" BOOLEAN DEFAULT false,
    "quota" TEXT DEFAULT 'GENERAL' CHECK ("quota" IN ('GENERAL', 'RTE', 'MANAGEMENT', 'STAFF_WARD')),
    "status" TEXT NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'ASSESSMENT', 'OFFERED', 'WAITLISTED', 'REJECTED', 'ACCEPTED', 'ENROLLED', 'WITHDRAWN')),
    "application_fee_id" BIGINT,
    "applicant_user_id" BIGINT,
    "decided_by_user_id" BIGINT,
    "submitted_at" TIMESTAMPTZ,
    "decided_at" TIMESTAMPTZ,
    "student_id" BIGINT,
    CONSTRAINT "admissions_application_pkey" PRIMARY KEY ("application_id"),
    CONSTRAINT "admissions_application_tenant_key" UNIQUE ("school_id", "application_id"),
    CONSTRAINT "admissions_application_application_number_key" UNIQUE ("school_id", "application_number")
);

CREATE TABLE "admissions"."assessment" (
    "school_id" BIGINT NOT NULL,
    "assessment_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "application_id" BIGINT NOT NULL,
    "kind" TEXT CHECK ("kind" IN ('ENTRANCE_TEST', 'INTERACTION', 'INTERVIEW')),
    "scheduled_at" TIMESTAMPTZ,
    "max_score" NUMERIC(14,2),
    "score" NUMERIC(14,2),
    "remarks" TEXT,
    "assessed_by_user_id" BIGINT,
    CONSTRAINT "admissions_assessment_pkey" PRIMARY KEY ("assessment_id"),
    CONSTRAINT "admissions_assessment_tenant_key" UNIQUE ("school_id", "assessment_id")
);

CREATE TABLE "admissions"."reenrollment" (
    "school_id" BIGINT NOT NULL,
    "reenrollment_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "academic_year_id" BIGINT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'INVITED' CHECK ("status" IN ('INVITED', 'CONFIRMED', 'DECLINED', 'LEAVING')),
    "responded_by_user_id" BIGINT,
    "responded_at" TIMESTAMPTZ,
    "leaving_reason" TEXT,
    CONSTRAINT "admissions_reenrollment_pkey" PRIMARY KEY ("reenrollment_id"),
    CONSTRAINT "admissions_reenrollment_tenant_key" UNIQUE ("school_id", "reenrollment_id")
);

-- ---------------------------------------------------------------------------
-- finance
-- ---------------------------------------------------------------------------

CREATE TABLE "finance"."fee_head" (
    "school_id" BIGINT NOT NULL,
    "fee_head_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "is_refundable" BOOLEAN DEFAULT false,
    "gst_rate" NUMERIC(14,2),
    "gl_account_code" TEXT,
    CONSTRAINT "finance_fee_head_pkey" PRIMARY KEY ("fee_head_id"),
    CONSTRAINT "finance_fee_head_tenant_key" UNIQUE ("school_id", "fee_head_id"),
    CONSTRAINT "finance_fee_head_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "finance"."concession_type" (
    "school_id" BIGINT NOT NULL,
    "concession_type_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "calc" TEXT NOT NULL CHECK ("calc" IN ('PERCENT', 'FIXED')),
    "value" NUMERIC(14,2) NOT NULL,
    "fee_head_id" BIGINT,
    CONSTRAINT "finance_concession_type_pkey" PRIMARY KEY ("concession_type_id"),
    CONSTRAINT "finance_concession_type_tenant_key" UNIQUE ("school_id", "concession_type_id"),
    CONSTRAINT "finance_concession_type_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "finance"."student_concession" (
    "school_id" BIGINT NOT NULL,
    "student_concession_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "concession_type_id" BIGINT NOT NULL,
    "academic_year_id" BIGINT,
    "reason" TEXT,
    "status" TEXT NOT NULL DEFAULT 'REQUESTED' CHECK ("status" IN ('REQUESTED', 'APPROVED', 'REJECTED', 'REVOKED')),
    "approved_by_user_id" BIGINT,
    "approved_at" TIMESTAMPTZ,
    CONSTRAINT "finance_student_concession_pkey" PRIMARY KEY ("student_concession_id"),
    CONSTRAINT "finance_student_concession_tenant_key" UNIQUE ("school_id", "student_concession_id")
);

CREATE TABLE "finance"."late_fee_rule" (
    "school_id" BIGINT NOT NULL,
    "rule_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "fee_structure_id" BIGINT NOT NULL,
    "grace_days" INTEGER DEFAULT 0,
    "calc" TEXT NOT NULL CHECK ("calc" IN ('PER_DAY', 'FLAT', 'PERCENT')),
    "amount" NUMERIC(14,2) NOT NULL,
    "cap" NUMERIC(14,2),
    CONSTRAINT "finance_late_fee_rule_pkey" PRIMARY KEY ("rule_id"),
    CONSTRAINT "finance_late_fee_rule_tenant_key" UNIQUE ("school_id", "rule_id")
);

CREATE TABLE "finance"."payment" (
    "school_id" BIGINT NOT NULL,
    "payment_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "paid_by_user_id" BIGINT,
    "amount" NUMERIC(14,2) NOT NULL,
    "mode" TEXT NOT NULL CHECK ("mode" IN ('UPI', 'CARD', 'NETBANKING', 'CASH', 'CHEQUE', 'DD', 'BANK_TRANSFER', 'WALLET')),
    "gateway" TEXT DEFAULT 'NONE' CHECK ("gateway" IN ('RAZORPAY', 'PAYU', 'CCAVENUE', 'NONE')),
    "gateway_txn_id" TEXT,
    "idempotency_key" TEXT,
    "cheque_number" TEXT,
    "bank_name" TEXT,
    "receipt_number" TEXT,
    "status" TEXT NOT NULL DEFAULT 'INITIATED' CHECK ("status" IN ('INITIATED', 'SUCCESS', 'FAILED', 'BOUNCED', 'REFUNDED', 'PARTIALLY_REFUNDED')),
    "received_by_user_id" BIGINT,
    "paid_at" TIMESTAMPTZ,
    CONSTRAINT "finance_payment_pkey" PRIMARY KEY ("payment_id"),
    CONSTRAINT "finance_payment_tenant_key" UNIQUE ("school_id", "payment_id"),
    CONSTRAINT "finance_payment_gateway_txn_id_key" UNIQUE ("school_id", "gateway_txn_id"),
    CONSTRAINT "finance_payment_idempotency_key_key" UNIQUE ("school_id", "idempotency_key"),
    CONSTRAINT "finance_payment_receipt_number_key" UNIQUE ("school_id", "receipt_number")
);

CREATE TABLE "finance"."payment_allocation" (
    "school_id" BIGINT NOT NULL,
    "allocation_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "payment_id" BIGINT NOT NULL,
    "fee_id" BIGINT NOT NULL,
    "amount" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "finance_payment_allocation_pkey" PRIMARY KEY ("allocation_id"),
    CONSTRAINT "finance_payment_allocation_tenant_key" UNIQUE ("school_id", "allocation_id")
);

CREATE TABLE "finance"."refund" (
    "school_id" BIGINT NOT NULL,
    "refund_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "payment_id" BIGINT NOT NULL,
    "amount" NUMERIC(14,2) NOT NULL,
    "reason" TEXT CHECK ("reason" IN ('EXCESS', 'DEPOSIT', 'WITHDRAWAL', 'CANCELLED_SERVICE')),
    "status" TEXT NOT NULL DEFAULT 'REQUESTED' CHECK ("status" IN ('REQUESTED', 'APPROVED', 'PAID', 'REJECTED')),
    "approved_by_user_id" BIGINT,
    "gateway_refund_id" TEXT,
    "refunded_at" TIMESTAMPTZ,
    CONSTRAINT "finance_refund_pkey" PRIMARY KEY ("refund_id"),
    CONSTRAINT "finance_refund_tenant_key" UNIQUE ("school_id", "refund_id")
);

CREATE TABLE "finance"."student_wallet" (
    "school_id" BIGINT NOT NULL,
    "wallet_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "balance" NUMERIC(14,2) NOT NULL DEFAULT 0,
    "monthly_limit" NUMERIC(14,2),
    "is_frozen" BOOLEAN DEFAULT false,
    CONSTRAINT "finance_student_wallet_pkey" PRIMARY KEY ("wallet_id"),
    CONSTRAINT "finance_student_wallet_tenant_key" UNIQUE ("school_id", "wallet_id"),
    CONSTRAINT "finance_student_wallet_student_id_key" UNIQUE ("school_id", "student_id")
);

CREATE TABLE "finance"."wallet_txn" (
    "school_id" BIGINT NOT NULL,
    "wallet_txn_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "wallet_id" BIGINT NOT NULL,
    "txn_type" TEXT NOT NULL CHECK ("txn_type" IN ('TOP_UP', 'CASH_WITHDRAWAL', 'STORE_PURCHASE', 'REFUND', 'ADJUSTMENT')),
    "amount" NUMERIC(14,2) NOT NULL,
    "payment_id" BIGINT,
    "store_sale_id" BIGINT,
    "performed_by_user_id" BIGINT,
    "witnessed_by_user_id" BIGINT,
    "txn_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "note" TEXT,
    CONSTRAINT "finance_wallet_txn_pkey" PRIMARY KEY ("wallet_txn_id"),
    CONSTRAINT "finance_wallet_txn_tenant_key" UNIQUE ("school_id", "wallet_txn_id")
);

