-- hostel
-- ---------------------------------------------------------------------------

CREATE TABLE "hostel"."hostel" (
    "school_id" BIGINT NOT NULL,
    "hostel_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "gender" TEXT CHECK ("gender" IN ('BOYS', 'GIRLS', 'CO_ED')),
    "hostel_type" TEXT CHECK ("hostel_type" IN ('SCHOOL_BOARDING', 'COLLEGE', 'STAFF_QUARTERS')),
    "location_id" BIGINT,
    "capacity" INTEGER,
    "curfew_weekday" TIME,
    "curfew_weekend" TIME,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'CLOSED_FOR_VACATION', 'INACTIVE')),
    CONSTRAINT "hostel_hostel_pkey" PRIMARY KEY ("hostel_id"),
    CONSTRAINT "hostel_hostel_tenant_key" UNIQUE ("school_id", "hostel_id"),
    CONSTRAINT "hostel_hostel_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "hostel"."block" (
    "school_id" BIGINT NOT NULL,
    "block_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "name" TEXT NOT NULL,
    "floor_count" INTEGER,
    CONSTRAINT "hostel_block_pkey" PRIMARY KEY ("block_id"),
    CONSTRAINT "hostel_block_tenant_key" UNIQUE ("school_id", "block_id")
);

CREATE TABLE "hostel"."room" (
    "school_id" BIGINT NOT NULL,
    "room_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "block_id" BIGINT,
    "floor_number" INTEGER,
    "room_number" TEXT NOT NULL,
    "room_type" TEXT CHECK ("room_type" IN ('SINGLE', 'DOUBLE', 'TRIPLE', 'DORM')),
    "capacity" INTEGER,
    "is_ac" BOOLEAN DEFAULT false,
    "has_attached_bath" BOOLEAN DEFAULT false,
    "location_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK ("status" IN ('AVAILABLE', 'FULL', 'MAINTENANCE', 'BLOCKED')),
    CONSTRAINT "hostel_room_pkey" PRIMARY KEY ("room_id"),
    CONSTRAINT "hostel_room_tenant_key" UNIQUE ("school_id", "room_id"),
    CONSTRAINT "hostel_room_room_number_key" UNIQUE ("school_id", "hostel_id", "room_number")
);

CREATE TABLE "hostel"."bed" (
    "school_id" BIGINT NOT NULL,
    "bed_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "room_id" BIGINT NOT NULL,
    "bed_label" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'VACANT' CHECK ("status" IN ('VACANT', 'OCCUPIED', 'BLOCKED', 'MAINTENANCE')),
    CONSTRAINT "hostel_bed_pkey" PRIMARY KEY ("bed_id"),
    CONSTRAINT "hostel_bed_tenant_key" UNIQUE ("school_id", "bed_id")
);

CREATE TABLE "hostel"."fee_plan" (
    "school_id" BIGINT NOT NULL,
    "fee_plan_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "room_type" TEXT,
    "is_ac" BOOLEAN,
    "fee_structure_id" BIGINT,
    "caution_deposit" NUMERIC(14,2),
    CONSTRAINT "hostel_fee_plan_pkey" PRIMARY KEY ("fee_plan_id"),
    CONSTRAINT "hostel_fee_plan_tenant_key" UNIQUE ("school_id", "fee_plan_id")
);

CREATE TABLE "hostel"."allocation_request" (
    "school_id" BIGINT NOT NULL,
    "request_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "academic_year_id" BIGINT,
    "kind" TEXT NOT NULL CHECK ("kind" IN ('NEW', 'ROOM_CHANGE', 'VACATE')),
    "preferred_hostel_id" BIGINT,
    "preferred_room_type" TEXT,
    "roommate_pref_student_id" BIGINT,
    "reason" TEXT,
    "status" TEXT NOT NULL DEFAULT 'REQUESTED' CHECK ("status" IN ('REQUESTED', 'APPROVED', 'WAITLISTED', 'REJECTED', 'DONE')),
    "requested_by_user_id" BIGINT,
    "decided_by_user_id" BIGINT,
    CONSTRAINT "hostel_allocation_request_pkey" PRIMARY KEY ("request_id"),
    CONSTRAINT "hostel_allocation_request_tenant_key" UNIQUE ("school_id", "request_id")
);

CREATE TABLE "hostel"."allocation" (
    "school_id" BIGINT NOT NULL,
    "allocation_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "bed_id" BIGINT NOT NULL,
    "room_id" BIGINT NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "academic_year_id" BIGINT,
    "fee_plan_id" BIGINT,
    "check_in_date" DATE NOT NULL,
    "check_out_date" DATE,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'VACATED', 'TRANSFERRED', 'SUSPENDED')),
    "is_room_leader" BOOLEAN DEFAULT false,
    "allocated_by_user_id" BIGINT,
    "request_id" BIGINT,
    CONSTRAINT "hostel_allocation_pkey" PRIMARY KEY ("allocation_id"),
    CONSTRAINT "hostel_allocation_tenant_key" UNIQUE ("school_id", "allocation_id")
);

CREATE TABLE "hostel"."staff_assignment" (
    "school_id" BIGINT NOT NULL,
    "assignment_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "duty" TEXT NOT NULL CHECK ("duty" IN ('CHIEF_WARDEN', 'BLOCK_WARDEN', 'FLOOR_WARDEN', 'ROOM_WARDEN', 'ASSISTANT_WARDEN', 'MATRON', 'MESS_INCHARGE')),
    "scope_type" TEXT NOT NULL CHECK ("scope_type" IN ('HOSTEL', 'BLOCK', 'FLOOR', 'ROOMS')),
    "block_id" BIGINT,
    "floor_number" INTEGER,
    "is_resident" BOOLEAN DEFAULT false,
    "from_date" DATE NOT NULL,
    "to_date" DATE,
    "assigned_by_user_id" BIGINT,
    CONSTRAINT "hostel_staff_assignment_pkey" PRIMARY KEY ("assignment_id"),
    CONSTRAINT "hostel_staff_assignment_tenant_key" UNIQUE ("school_id", "assignment_id")
);

CREATE TABLE "hostel"."staff_assignment_room" (
    "school_id" BIGINT NOT NULL,
    "assignment_id" BIGINT NOT NULL,
    "room_id" BIGINT NOT NULL,
    CONSTRAINT "hostel_staff_assignment_room_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "assignment_id", "room_id")
);

CREATE TABLE "hostel"."roll_call" (
    "school_id" BIGINT NOT NULL,
    "roll_call_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "assignment_id" BIGINT,
    "session" TEXT NOT NULL CHECK ("session" IN ('MORNING', 'STUDY_HOUR', 'NIGHT', 'EMERGENCY', 'CUSTOM')),
    "roll_date" DATE NOT NULL,
    "conducted_by_user_id" BIGINT,
    "roster_entry_id" BIGINT,
    "started_at" TIMESTAMPTZ,
    "submitted_at" TIMESTAMPTZ,
    "status" TEXT NOT NULL DEFAULT 'OPEN' CHECK ("status" IN ('OPEN', 'SUBMITTED', 'ESCALATED')),
    CONSTRAINT "hostel_roll_call_pkey" PRIMARY KEY ("roll_call_id"),
    CONSTRAINT "hostel_roll_call_tenant_key" UNIQUE ("school_id", "roll_call_id")
);

CREATE TABLE "hostel"."roll_call_entry" (
    "school_id" BIGINT NOT NULL,
    "entry_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "roll_call_id" BIGINT NOT NULL,
    "student_id" BIGINT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'PRESENT' CHECK ("status" IN ('PRESENT', 'ABSENT', 'ON_OUTING', 'ON_LEAVE', 'SICK_BAY', 'EXCUSED')),
    "outing_id" BIGINT,
    "custody_pending" BOOLEAN DEFAULT false,
    "note" TEXT,
    CONSTRAINT "hostel_roll_call_entry_pkey" PRIMARY KEY ("entry_id"),
    CONSTRAINT "hostel_roll_call_entry_tenant_key" UNIQUE ("school_id", "entry_id"),
    CONSTRAINT "hostel_roll_call_entry_uq1" UNIQUE ("school_id", "roll_call_id", "student_id")
);

CREATE TABLE "hostel"."room_inspection" (
    "school_id" BIGINT NOT NULL,
    "inspection_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "room_id" BIGINT NOT NULL,
    "allocation_id" BIGINT,
    "kind" TEXT NOT NULL CHECK ("kind" IN ('CHECK_IN', 'CHECK_OUT', 'ROUTINE_HYGIENE', 'CONTRABAND')),
    "inspected_by_user_id" BIGINT,
    "inspected_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "hygiene_score" INTEGER,
    "findings" TEXT,
    "photo_urls" TEXT[],
    "damage_charge" NUMERIC(14,2),
    "charged_student_id" BIGINT,
    "damage_fee_id" BIGINT,
    "incident_id" BIGINT,
    CONSTRAINT "hostel_room_inspection_pkey" PRIMARY KEY ("inspection_id"),
    CONSTRAINT "hostel_room_inspection_tenant_key" UNIQUE ("school_id", "inspection_id")
);

CREATE TABLE "hostel"."laundry_batch" (
    "school_id" BIGINT NOT NULL,
    "batch_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "student_id" BIGINT NOT NULL,
    "given_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "item_count" INTEGER,
    "returned_at" TIMESTAMPTZ,
    "returned_count" INTEGER,
    "missing_count" INTEGER,
    "handled_by_user_id" BIGINT,
    CONSTRAINT "hostel_laundry_batch_pkey" PRIMARY KEY ("batch_id"),
    CONSTRAINT "hostel_laundry_batch_tenant_key" UNIQUE ("school_id", "batch_id")
);

CREATE TABLE "hostel"."outing_policy" (
    "school_id" BIGINT NOT NULL,
    "policy_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "outing_type" TEXT NOT NULL CHECK ("outing_type" IN ('LOCAL_OUTING', 'DAY_OUT', 'WEEKEND_HOME', 'HOME_LEAVE', 'VACATION', 'MEDICAL', 'EMERGENCY', 'OFFICIAL')),
    "min_level" TEXT CHECK ("min_level" IN ('PRIMARY', 'SECONDARY', 'UG', 'PG')),
    "allowed_days" TEXT,
    "max_per_month" INTEGER,
    "max_hours" INTEGER,
    "requires_parent_approval" BOOLEAN DEFAULT true,
    "requires_pickup_person" BOOLEAN DEFAULT false,
    "approver_duty" TEXT CHECK ("approver_duty" IN ('BLOCK_WARDEN', 'CHIEF_WARDEN')),
    "allow_phone_release" BOOLEAN DEFAULT false,
    "phone_release_at" TEXT CHECK ("phone_release_at" IN ('GATE_EXIT', 'GROUP_RELEASE_TIME')),
    "grace_minutes" INTEGER DEFAULT 15,
    CONSTRAINT "hostel_outing_policy_pkey" PRIMARY KEY ("policy_id"),
    CONSTRAINT "hostel_outing_policy_tenant_key" UNIQUE ("school_id", "policy_id")
);

CREATE TABLE "hostel"."outing_group" (
    "school_id" BIGINT NOT NULL,
    "group_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "group_kind" TEXT NOT NULL CHECK ("group_kind" IN ('STATION_DROP', 'VACATION_DEPARTURE', 'FIELD_TRIP', 'MARKET_OUTING', 'EVENT')),
    "title" TEXT NOT NULL,
    "travel_mode" TEXT CHECK ("travel_mode" IN ('TRAIN', 'BUS', 'SCHOOL_VEHICLE', 'FLIGHT', 'WALK')),
    "carrier_ref" TEXT,
    "station_or_stop" TEXT,
    "campus_departure_at" TIMESTAMPTZ,
    "carrier_departure_at" TIMESTAMPTZ,
    "phone_release_at" TIMESTAMPTZ,
    "escort_user_id" BIGINT,
    "vehicle_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'PLANNED' CHECK ("status" IN ('PLANNED', 'DEPARTED', 'COMPLETED', 'CANCELLED')),
    CONSTRAINT "hostel_outing_group_pkey" PRIMARY KEY ("group_id"),
    CONSTRAINT "hostel_outing_group_tenant_key" UNIQUE ("school_id", "group_id")
);

CREATE TABLE "hostel"."outing_request" (
    "school_id" BIGINT NOT NULL,
    "outing_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "policy_id" BIGINT,
    "group_id" BIGINT,
    "outing_type" TEXT NOT NULL CHECK ("outing_type" IN ('LOCAL_OUTING', 'DAY_OUT', 'WEEKEND_HOME', 'HOME_LEAVE', 'VACATION', 'MEDICAL', 'EMERGENCY', 'OFFICIAL')),
    "purpose" TEXT,
    "destination" TEXT,
    "depart_planned_at" TIMESTAMPTZ NOT NULL,
    "return_planned_at" TIMESTAMPTZ NOT NULL,
    "travel_mode" TEXT CHECK ("travel_mode" IN ('SELF', 'PARENT_PICKUP', 'AUTHORISED_PICKUP', 'SCHOOL_VEHICLE', 'TRAIN', 'BUS', 'FLIGHT')),
    "travel_ref" TEXT,
    "travel_departure_at" TIMESTAMPTZ,
    "pickup_person_id" BIGINT,
    "requested_by_kind" TEXT NOT NULL CHECK ("requested_by_kind" IN ('PARENT', 'STUDENT', 'WARDEN')),
    "requested_by_user_id" BIGINT,
    "parent_status" TEXT NOT NULL DEFAULT 'PENDING' CHECK ("parent_status" IN ('NOT_REQUIRED', 'PENDING', 'APPROVED', 'DECLINED')),
    "parent_user_id" BIGINT,
    "parent_decided_at" TIMESTAMPTZ,
    "warden_status" TEXT NOT NULL CHECK ("warden_status" IN ('PENDING', 'APPROVED', 'REJECTED')),
    "warden_user_id" BIGINT,
    "warden_decided_at" TIMESTAMPTZ,
    "confirmed_by_user_id" BIGINT,
    "release_custody_items" BOOLEAN DEFAULT false,
    "gate_pass_token" TEXT,
    "status" TEXT NOT NULL DEFAULT 'REQUESTED' CHECK ("status" IN ('REQUESTED', 'APPROVED', 'REJECTED', 'CANCELLED', 'OUT', 'RETURNED', 'OVERDUE', 'CLOSED')),
    "late_minutes" INTEGER,
    CONSTRAINT "hostel_outing_request_pkey" PRIMARY KEY ("outing_id"),
    CONSTRAINT "hostel_outing_request_tenant_key" UNIQUE ("school_id", "outing_id"),
    CONSTRAINT "hostel_outing_request_gate_pass_token_key" UNIQUE ("school_id", "gate_pass_token")
);

CREATE TABLE "hostel"."outing_movement" (
    "school_id" BIGINT NOT NULL,
    "movement_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "outing_id" BIGINT NOT NULL,
    "direction" TEXT NOT NULL CHECK ("direction" IN ('OUT', 'IN')),
    "moved_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "gate_user_id" BIGINT,
    "roster_entry_id" BIGINT,
    "verified_pickup_person_id" BIGINT,
    "verification" TEXT CHECK ("verification" IN ('QR', 'PARENT_OTP', 'PHOTO_ID', 'FACE')),
    "punch_id" BIGINT,
    CONSTRAINT "hostel_outing_movement_pkey" PRIMARY KEY ("movement_id"),
    CONSTRAINT "hostel_outing_movement_tenant_key" UNIQUE ("school_id", "movement_id")
);

-- ---------------------------------------------------------------------------
-- frontoffice
-- ---------------------------------------------------------------------------

CREATE TABLE "frontoffice"."pickup_person" (
    "school_id" BIGINT NOT NULL,
    "pickup_person_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "name" TEXT NOT NULL,
    "relationship" TEXT,
    "phone" TEXT,
    "photo_url" TEXT,
    "id_proof_last4" TEXT,
    "added_by_user_id" BIGINT,
    "requires_parent_otp" BOOLEAN DEFAULT true,
    "valid_from" DATE,
    "valid_to" DATE,
    "is_active" BOOLEAN DEFAULT true,
    CONSTRAINT "frontoffice_pickup_person_pkey" PRIMARY KEY ("pickup_person_id"),
    CONSTRAINT "frontoffice_pickup_person_tenant_key" UNIQUE ("school_id", "pickup_person_id")
);

-- ---------------------------------------------------------------------------
-- hostel
-- ---------------------------------------------------------------------------

CREATE TABLE "hostel"."mess" (
    "school_id" BIGINT NOT NULL,
    "mess_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT,
    "name" TEXT NOT NULL,
    "vendor_id" BIGINT,
    "store_location_id" BIGINT,
    "capacity" INTEGER,
    CONSTRAINT "hostel_mess_pkey" PRIMARY KEY ("mess_id"),
    CONSTRAINT "hostel_mess_tenant_key" UNIQUE ("school_id", "mess_id")
);

CREATE TABLE "hostel"."mess_plan" (
    "school_id" BIGINT NOT NULL,
    "plan_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "mess_id" BIGINT NOT NULL,
    "name" TEXT NOT NULL CHECK ("name" IN ('VEG', 'NON_VEG', 'JAIN', 'CUSTOM')),
    "meals_included" TEXT,
    "fee_structure_id" BIGINT,
    "rebate_after_days" INTEGER,
    "rebate_per_day" NUMERIC(14,2),
    CONSTRAINT "hostel_mess_plan_pkey" PRIMARY KEY ("plan_id"),
    CONSTRAINT "hostel_mess_plan_tenant_key" UNIQUE ("school_id", "plan_id")
);

CREATE TABLE "hostel"."mess_subscription" (
    "school_id" BIGINT NOT NULL,
    "subscription_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "plan_id" BIGINT NOT NULL,
    "student_id" BIGINT,
    "user_id" BIGINT,
    "from_date" DATE NOT NULL,
    "to_date" DATE,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'PAUSED', 'ENDED')),
    CONSTRAINT "hostel_mess_subscription_pkey" PRIMARY KEY ("subscription_id"),
    CONSTRAINT "hostel_mess_subscription_tenant_key" UNIQUE ("school_id", "subscription_id")
);

CREATE TABLE "hostel"."mess_menu" (
    "school_id" BIGINT NOT NULL,
    "menu_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "mess_id" BIGINT NOT NULL,
    "day_of_week" TEXT CHECK ("day_of_week" IN ('MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT', 'SUN')),
    "menu_date" DATE,
    "meal" TEXT NOT NULL CHECK ("meal" IN ('BREAKFAST', 'LUNCH', 'SNACKS', 'DINNER')),
    "items" TEXT NOT NULL,
    "is_special" BOOLEAN DEFAULT false,
    CONSTRAINT "hostel_mess_menu_pkey" PRIMARY KEY ("menu_id"),
    CONSTRAINT "hostel_mess_menu_tenant_key" UNIQUE ("school_id", "menu_id")
);

CREATE TABLE "hostel"."meal_attendance" (
    "school_id" BIGINT NOT NULL,
    "meal_attendance_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "mess_id" BIGINT NOT NULL,
    "subscription_id" BIGINT NOT NULL,
    "meal_date" DATE NOT NULL,
    "meal" TEXT NOT NULL CHECK ("meal" IN ('BREAKFAST', 'LUNCH', 'SNACKS', 'DINNER')),
    "status" TEXT NOT NULL DEFAULT 'TAKEN' CHECK ("status" IN ('TAKEN', 'SKIPPED', 'ON_LEAVE')),
    "source" TEXT CHECK ("source" IN ('SCAN', 'MANUAL')),
    CONSTRAINT "hostel_meal_attendance_pkey" PRIMARY KEY ("meal_attendance_id"),
    CONSTRAINT "hostel_meal_attendance_tenant_key" UNIQUE ("school_id", "meal_attendance_id"),
    CONSTRAINT "hostel_meal_attendance_uq1" UNIQUE ("school_id", "subscription_id", "meal_date", "meal")
);

CREATE TABLE "hostel"."mess_rebate" (
    "school_id" BIGINT NOT NULL,
    "rebate_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "subscription_id" BIGINT NOT NULL,
    "outing_id" BIGINT,
    "days" INTEGER NOT NULL,
    "amount" NUMERIC(14,2) NOT NULL,
    "credit_fee_id" BIGINT,
    CONSTRAINT "hostel_mess_rebate_pkey" PRIMARY KEY ("rebate_id"),
    CONSTRAINT "hostel_mess_rebate_tenant_key" UNIQUE ("school_id", "rebate_id")
);

CREATE TABLE "hostel"."mess_feedback" (
    "school_id" BIGINT NOT NULL,
    "feedback_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "mess_id" BIGINT NOT NULL,
    "student_id" BIGINT,
    "meal_date" DATE NOT NULL,
    "meal" TEXT CHECK ("meal" IN ('BREAKFAST', 'LUNCH', 'SNACKS', 'DINNER')),
    "rating" INTEGER NOT NULL,
    "comment" TEXT,
    CONSTRAINT "hostel_mess_feedback_pkey" PRIMARY KEY ("feedback_id"),
    CONSTRAINT "hostel_mess_feedback_tenant_key" UNIQUE ("school_id", "feedback_id")
);

-- ---------------------------------------------------------------------------
-- custody
-- ---------------------------------------------------------------------------

CREATE TABLE "custody"."storage_unit" (
    "school_id" BIGINT NOT NULL,
    "unit_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "location_id" BIGINT,
    "hostel_id" BIGINT,
    "code" TEXT NOT NULL,
    "unit_type" TEXT NOT NULL CHECK ("unit_type" IN ('LOCKER', 'TRAY', 'SAFE', 'SHELF')),
    "capacity" INTEGER,
    "assigned_student_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'FULL', 'OUT_OF_SERVICE')),
    CONSTRAINT "custody_storage_unit_pkey" PRIMARY KEY ("unit_id"),
    CONSTRAINT "custody_storage_unit_tenant_key" UNIQUE ("school_id", "unit_id"),
    CONSTRAINT "custody_storage_unit_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "custody"."item" (
    "school_id" BIGINT NOT NULL,
    "item_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "student_id" BIGINT NOT NULL,
    "item_type" TEXT NOT NULL CHECK ("item_type" IN ('MOBILE_PHONE', 'LAPTOP', 'TABLET', 'SMARTWATCH', 'CHARGER', 'ID_DOCUMENT', 'JEWELLERY', 'OTHER')),
    "brand" TEXT,
    "model" TEXT,
    "serial_last4" TEXT,
    "colour" TEXT,
    "description" TEXT,
    "photo_urls" TEXT[],
    "declared_value" NUMERIC(14,2),
    "tag_code" TEXT,
    "storage_unit_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'IN_CUSTODY' CHECK ("status" IN ('IN_CUSTODY', 'RELEASED_TEMP', 'RELEASED_TRAVEL', 'WITH_PARENT', 'CONFISCATED', 'LOST', 'DAMAGED', 'CLOSED')),
    "due_back_at" TIMESTAMPTZ,
    "registered_by_user_id" BIGINT,
    "registered_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "custody_item_pkey" PRIMARY KEY ("item_id"),
    CONSTRAINT "custody_item_tenant_key" UNIQUE ("school_id", "item_id"),
    CONSTRAINT "custody_item_tag_code_key" UNIQUE ("school_id", "tag_code")
);

CREATE TABLE "custody"."release_window" (
    "school_id" BIGINT NOT NULL,
    "window_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "hostel_id" BIGINT NOT NULL,
    "name" TEXT NOT NULL,
    "day_of_week" TEXT NOT NULL CHECK ("day_of_week" IN ('MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT', 'SUN')),
    "start_time" TIME NOT NULL,
    "end_time" TIME NOT NULL,
    "item_types" TEXT,
    "min_level" TEXT,
    "is_active" BOOLEAN DEFAULT true,
    CONSTRAINT "custody_release_window_pkey" PRIMARY KEY ("window_id"),
    CONSTRAINT "custody_release_window_tenant_key" UNIQUE ("school_id", "window_id")
);

CREATE TABLE "custody"."event" (
    "school_id" BIGINT NOT NULL,
    "event_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" BIGINT NOT NULL,
    "event_type" TEXT NOT NULL CHECK ("event_type" IN ('DEPOSIT', 'RELEASE', 'RETURN', 'MOVE_UNIT', 'CONFISCATE', 'HANDOVER_PARENT', 'INSPECT', 'MARK_LOST', 'MARK_DAMAGED', 'CLOSE')),
    "release_reason" TEXT CHECK ("release_reason" IN ('TRAVEL_HOME', 'OUTING', 'CALL_HOUR', 'ONLINE_EXAM', 'MEDICAL', 'PARENT_COLLECT', 'LEAVING_SCHOOL')),
    "outing_id" BIGINT,
    "group_id" BIGINT,
    "window_id" BIGINT,
    "incident_id" BIGINT,
    "from_unit_id" BIGINT,
    "to_unit_id" BIGINT,
    "performed_by_user_id" BIGINT NOT NULL,
    "counterparty_kind" TEXT CHECK ("counterparty_kind" IN ('STUDENT', 'PARENT', 'PICKUP_PERSON')),
    "counterparty_user_id" BIGINT,
    "counterparty_pickup_person_id" BIGINT,
    "verification" TEXT CHECK ("verification" IN ('QR', 'STUDENT_OTP', 'PARENT_OTP', 'SIGNATURE', 'FACE')),
    "condition_note" TEXT,
    "photo_url" TEXT,
    "due_back_at" TIMESTAMPTZ,
    "occurred_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "custody_event_pkey" PRIMARY KEY ("event_id"),
    CONSTRAINT "custody_event_tenant_key" UNIQUE ("school_id", "event_id")
);

-- ---------------------------------------------------------------------------
-- inventory
-- ---------------------------------------------------------------------------

CREATE TABLE "inventory"."item_category" (
    "school_id" BIGINT NOT NULL,
    "category_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "parent_category_id" BIGINT,
    "name" TEXT NOT NULL,
    CONSTRAINT "inventory_item_category_pkey" PRIMARY KEY ("category_id"),
    CONSTRAINT "inventory_item_category_tenant_key" UNIQUE ("school_id", "category_id")
);

CREATE TABLE "inventory"."vendor" (
    "school_id" BIGINT NOT NULL,
    "vendor_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" TEXT NOT NULL,
    "gstin" TEXT,
    "phone" TEXT,
    "email" TEXT,
    "address" TEXT,
    "payment_terms_days" INTEGER,
    "rating" INTEGER,
    "is_active" BOOLEAN DEFAULT true,
    CONSTRAINT "inventory_vendor_pkey" PRIMARY KEY ("vendor_id"),
    CONSTRAINT "inventory_vendor_tenant_key" UNIQUE ("school_id", "vendor_id")
);

CREATE TABLE "inventory"."requisition" (
    "school_id" BIGINT NOT NULL,
    "requisition_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "requisition_number" TEXT NOT NULL,
    "requested_by_user_id" BIGINT,
    "department_id" BIGINT,
    "cost_centre" TEXT CHECK ("cost_centre" IN ('SCHOOL', 'HOSTEL', 'MESS', 'TRANSPORT', 'DEPARTMENT')),
    "hostel_id" BIGINT,
    "needed_by" DATE,
    "justification" TEXT,
    "estimated_total" NUMERIC(14,2),
    "status" TEXT NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'SUBMITTED', 'APPROVED', 'REJECTED', 'ORDERED', 'ISSUED_FROM_STOCK', 'CLOSED')),
    CONSTRAINT "inventory_requisition_pkey" PRIMARY KEY ("requisition_id"),
    CONSTRAINT "inventory_requisition_tenant_key" UNIQUE ("school_id", "requisition_id"),
    CONSTRAINT "inventory_requisition_requisition_number_key" UNIQUE ("school_id", "requisition_number")
);

CREATE TABLE "inventory"."requisition_line" (
    "school_id" BIGINT NOT NULL,
    "line_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "requisition_id" BIGINT NOT NULL,
    "item_catalog_id" BIGINT NOT NULL,
    "quantity" NUMERIC(14,2) NOT NULL,
    "estimated_unit_cost" NUMERIC(14,2),
    CONSTRAINT "inventory_requisition_line_pkey" PRIMARY KEY ("line_id"),
    CONSTRAINT "inventory_requisition_line_tenant_key" UNIQUE ("school_id", "line_id")
);

CREATE TABLE "inventory"."purchase_order" (
    "school_id" BIGINT NOT NULL,
    "po_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "po_number" TEXT NOT NULL,
    "vendor_id" BIGINT NOT NULL,
    "requisition_id" BIGINT,
    "order_date" DATE,
    "expected_date" DATE,
    "subtotal" NUMERIC(14,2),
    "tax_amount" NUMERIC(14,2),
    "total_amount" NUMERIC(14,2),
    "status" TEXT NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'SENT', 'PARTIALLY_RECEIVED', 'RECEIVED', 'CANCELLED', 'CLOSED')),
    "created_by_user_id" BIGINT,
    CONSTRAINT "inventory_purchase_order_pkey" PRIMARY KEY ("po_id"),
    CONSTRAINT "inventory_purchase_order_tenant_key" UNIQUE ("school_id", "po_id"),
    CONSTRAINT "inventory_purchase_order_po_number_key" UNIQUE ("school_id", "po_number")
);

CREATE TABLE "inventory"."po_line" (
    "school_id" BIGINT NOT NULL,
    "po_line_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "po_id" BIGINT NOT NULL,
    "item_catalog_id" BIGINT NOT NULL,
    "quantity" NUMERIC(14,2) NOT NULL,
    "unit_price" NUMERIC(14,2) NOT NULL,
    "gst_rate" NUMERIC(14,2),
    "received_qty" NUMERIC(14,2) NOT NULL DEFAULT 0,
    CONSTRAINT "inventory_po_line_pkey" PRIMARY KEY ("po_line_id"),
    CONSTRAINT "inventory_po_line_tenant_key" UNIQUE ("school_id", "po_line_id")
);

CREATE TABLE "inventory"."goods_receipt" (
    "school_id" BIGINT NOT NULL,
    "grn_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "grn_number" TEXT NOT NULL,
    "po_id" BIGINT NOT NULL,
    "location_id" BIGINT NOT NULL,
    "received_by_user_id" BIGINT,
    "received_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "vendor_challan_no" TEXT,
    "status" TEXT NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'POSTED')),
    CONSTRAINT "inventory_goods_receipt_pkey" PRIMARY KEY ("grn_id"),
    CONSTRAINT "inventory_goods_receipt_tenant_key" UNIQUE ("school_id", "grn_id"),
    CONSTRAINT "inventory_goods_receipt_grn_number_key" UNIQUE ("school_id", "grn_number")
);

CREATE TABLE "inventory"."grn_line" (
    "school_id" BIGINT NOT NULL,
    "grn_line_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "grn_id" BIGINT NOT NULL,
    "po_line_id" BIGINT,
    "item_catalog_id" BIGINT NOT NULL,
    "received_qty" NUMERIC(14,2) NOT NULL,
    "accepted_qty" NUMERIC(14,2),
    "rejected_qty" NUMERIC(14,2),
    "unit_cost" NUMERIC(14,2),
    "batch_no" TEXT,
    "expiry_date" DATE,
    CONSTRAINT "inventory_grn_line_pkey" PRIMARY KEY ("grn_line_id"),
    CONSTRAINT "inventory_grn_line_tenant_key" UNIQUE ("school_id", "grn_line_id")
);

CREATE TABLE "inventory"."vendor_invoice" (
    "school_id" BIGINT NOT NULL,
    "invoice_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "vendor_id" BIGINT NOT NULL,
    "po_id" BIGINT,
    "invoice_number" TEXT NOT NULL,
    "invoice_date" DATE,
    "amount" NUMERIC(14,2) NOT NULL,
    "tax_amount" NUMERIC(14,2),
    "due_date" DATE,
    "match_status" TEXT DEFAULT 'UNMATCHED' CHECK ("match_status" IN ('UNMATCHED', 'MATCHED', 'MISMATCH')),
    "status" TEXT NOT NULL DEFAULT 'RECEIVED' CHECK ("status" IN ('RECEIVED', 'APPROVED', 'PAID', 'DISPUTED')),
    "document_id" BIGINT,
    CONSTRAINT "inventory_vendor_invoice_pkey" PRIMARY KEY ("invoice_id"),
    CONSTRAINT "inventory_vendor_invoice_tenant_key" UNIQUE ("school_id", "invoice_id"),
    CONSTRAINT "inventory_vendor_invoice_invoice_number_key" UNIQUE ("school_id", "vendor_id", "invoice_number")
);

CREATE TABLE "inventory"."stock_audit" (
    "school_id" BIGINT NOT NULL,
    "audit_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "location_id" BIGINT NOT NULL,
    "audit_date" DATE NOT NULL,
    "conducted_by_user_id" BIGINT,
    "approved_by_user_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'IN_PROGRESS' CHECK ("status" IN ('IN_PROGRESS', 'SUBMITTED', 'APPROVED')),
    CONSTRAINT "inventory_stock_audit_pkey" PRIMARY KEY ("audit_id"),
    CONSTRAINT "inventory_stock_audit_tenant_key" UNIQUE ("school_id", "audit_id")
);

CREATE TABLE "inventory"."stock_audit_line" (
    "school_id" BIGINT NOT NULL,
    "line_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "audit_id" BIGINT NOT NULL,
    "item_catalog_id" BIGINT NOT NULL,
    "asset_id" BIGINT,
    "system_qty" NUMERIC(14,2),
    "counted_qty" NUMERIC(14,2),
    "variance_reason" TEXT,
    "adjustment_txn_id" BIGINT,
    CONSTRAINT "inventory_stock_audit_line_pkey" PRIMARY KEY ("line_id"),
    CONSTRAINT "inventory_stock_audit_line_tenant_key" UNIQUE ("school_id", "line_id")
);

CREATE TABLE "inventory"."asset_maintenance" (
    "school_id" BIGINT NOT NULL,
    "maintenance_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "asset_id" BIGINT NOT NULL,
    "kind" TEXT NOT NULL CHECK ("kind" IN ('PREVENTIVE', 'REPAIR', 'AMC_VISIT', 'CALIBRATION')),
    "vendor_id" BIGINT,
    "ticket_id" BIGINT,
    "reported_at" TIMESTAMPTZ,
    "completed_at" TIMESTAMPTZ,
    "cost" NUMERIC(14,2),
    "expense_id" BIGINT,
    CONSTRAINT "inventory_asset_maintenance_pkey" PRIMARY KEY ("maintenance_id"),
    CONSTRAINT "inventory_asset_maintenance_tenant_key" UNIQUE ("school_id", "maintenance_id")
);

-- ---------------------------------------------------------------------------
-- accounts
-- ---------------------------------------------------------------------------

CREATE TABLE "accounts"."expense_head" (
    "school_id" BIGINT NOT NULL,
    "expense_head_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "parent_head_id" BIGINT,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "gl_account_code" TEXT,
    CONSTRAINT "accounts_expense_head_pkey" PRIMARY KEY ("expense_head_id"),
    CONSTRAINT "accounts_expense_head_tenant_key" UNIQUE ("school_id", "expense_head_id"),
    CONSTRAINT "accounts_expense_head_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "accounts"."budget" (
    "school_id" BIGINT NOT NULL,
    "budget_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "academic_year_id" BIGINT NOT NULL,
    "expense_head_id" BIGINT NOT NULL,
    "cost_centre" TEXT CHECK ("cost_centre" IN ('SCHOOL', 'HOSTEL', 'MESS', 'TRANSPORT', 'DEPARTMENT')),
    "hostel_id" BIGINT,
    "department_id" BIGINT,
    "amount" NUMERIC(14,2) NOT NULL,
    "alert_at_pct" NUMERIC(14,2) DEFAULT 80,
    CONSTRAINT "accounts_budget_pkey" PRIMARY KEY ("budget_id"),
    CONSTRAINT "accounts_budget_tenant_key" UNIQUE ("school_id", "budget_id")
);

CREATE TABLE "accounts"."expense" (
    "school_id" BIGINT NOT NULL,
    "expense_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "voucher_number" TEXT NOT NULL,
    "expense_head_id" BIGINT NOT NULL,
    "cost_centre" TEXT,
    "hostel_id" BIGINT,
    "department_id" BIGINT,
    "vendor_id" BIGINT,
    "vendor_invoice_id" BIGINT,
    "payroll_run_id" BIGINT,
    "expense_date" DATE NOT NULL,
    "amount" NUMERIC(14,2) NOT NULL,
    "tax_amount" NUMERIC(14,2),
    "payment_mode" TEXT CHECK ("payment_mode" IN ('BANK_TRANSFER', 'CHEQUE', 'UPI', 'CASH', 'CARD')),
    "paid_from" TEXT CHECK ("paid_from" IN ('BANK', 'PETTY_CASH')),
    "petty_cash_id" BIGINT,
    "reference_no" TEXT,
    "description" TEXT,
    "bill_document_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'SUBMITTED', 'APPROVED', 'REJECTED', 'PAID', 'CANCELLED')),
    "submitted_by_user_id" BIGINT,
    "paid_at" TIMESTAMPTZ,
    CONSTRAINT "accounts_expense_pkey" PRIMARY KEY ("expense_id"),
    CONSTRAINT "accounts_expense_tenant_key" UNIQUE ("school_id", "expense_id"),
    CONSTRAINT "accounts_expense_voucher_number_key" UNIQUE ("school_id", "voucher_number")
);

CREATE TABLE "accounts"."approval_rule" (
    "school_id" BIGINT NOT NULL,
    "rule_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ref_kind" TEXT NOT NULL CHECK ("ref_kind" IN ('EXPENSE', 'REQUISITION', 'PURCHASE_ORDER', 'REFUND', 'CONCESSION', 'PAYROLL')),
    "cost_centre" TEXT,
    "min_amount" NUMERIC(14,2),
    "max_amount" NUMERIC(14,2),
    "sequence" INTEGER NOT NULL DEFAULT 1,
    "approver_role_code" TEXT NOT NULL,
    CONSTRAINT "accounts_approval_rule_pkey" PRIMARY KEY ("rule_id"),
    CONSTRAINT "accounts_approval_rule_tenant_key" UNIQUE ("school_id", "rule_id")
);

CREATE TABLE "accounts"."approval" (
    "school_id" BIGINT NOT NULL,
    "approval_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ref_kind" TEXT NOT NULL,
    "ref_id" BIGINT NOT NULL,
    "rule_id" BIGINT,
    "sequence" INTEGER NOT NULL DEFAULT 1,
    "approver_user_id" BIGINT,
    "decision" TEXT NOT NULL CHECK ("decision" IN ('PENDING', 'APPROVED', 'REJECTED', 'SENT_BACK')),
    "note" TEXT,
    "decided_at" TIMESTAMPTZ,
    CONSTRAINT "accounts_approval_pkey" PRIMARY KEY ("approval_id"),
    CONSTRAINT "accounts_approval_tenant_key" UNIQUE ("school_id", "approval_id")
);

CREATE TABLE "accounts"."petty_cash_account" (
    "school_id" BIGINT NOT NULL,
    "petty_cash_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" TEXT NOT NULL,
    "custodian_user_id" BIGINT,
    "cost_centre" TEXT,
    "hostel_id" BIGINT,
    "float_limit" NUMERIC(14,2),
    "balance" NUMERIC(14,2) NOT NULL DEFAULT 0,
    CONSTRAINT "accounts_petty_cash_account_pkey" PRIMARY KEY ("petty_cash_id"),
    CONSTRAINT "accounts_petty_cash_account_tenant_key" UNIQUE ("school_id", "petty_cash_id")
);

CREATE TABLE "accounts"."petty_cash_txn" (
    "school_id" BIGINT NOT NULL,
    "txn_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "petty_cash_id" BIGINT NOT NULL,
    "txn_type" TEXT NOT NULL CHECK ("txn_type" IN ('TOP_UP', 'SPEND', 'RETURN', 'SETTLEMENT')),
    "amount" NUMERIC(14,2) NOT NULL,
    "expense_id" BIGINT,
    "performed_by_user_id" BIGINT,
    "txn_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "accounts_petty_cash_txn_pkey" PRIMARY KEY ("txn_id"),
    CONSTRAINT "accounts_petty_cash_txn_tenant_key" UNIQUE ("school_id", "txn_id")
);

CREATE TABLE "accounts"."other_income" (
    "school_id" BIGINT NOT NULL,
    "income_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "income_type" TEXT NOT NULL CHECK ("income_type" IN ('DONATION', 'RENT', 'CANTEEN', 'SCRAP_SALE', 'GRANT', 'OTHER')),
    "amount" NUMERIC(14,2) NOT NULL,
    "received_on" DATE NOT NULL,
    "payer" TEXT,
    "mode" TEXT,
    "document_id" BIGINT,
    "recorded_by_user_id" BIGINT,
    CONSTRAINT "accounts_other_income_pkey" PRIMARY KEY ("income_id"),
    CONSTRAINT "accounts_other_income_tenant_key" UNIQUE ("school_id", "income_id")
);

-- ---------------------------------------------------------------------------
-- hr
-- ---------------------------------------------------------------------------

CREATE TABLE "hr"."employee_profile" (
    "school_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "employee_code" TEXT,
    "staff_category" TEXT CHECK ("staff_category" IN ('TEACHING', 'NON_TEACHING', 'SECURITY', 'HOSTEL', 'TRANSPORT', 'CONTRACT')),
    "department_id" BIGINT,
    "designation" TEXT,
    "employment_type" TEXT CHECK ("employment_type" IN ('PERMANENT', 'PROBATION', 'CONTRACT', 'PART_TIME', 'GUEST', 'OUTSOURCED')),
    "reporting_manager_user_id" BIGINT,
    "date_of_joining" DATE,
    "date_of_leaving" DATE,
    "pf_uan" TEXT,
    "esi_number" TEXT,
    "vault_ref" TEXT,
    "police_verification_on" DATE,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'ON_NOTICE', 'LEFT')),
    CONSTRAINT "hr_employee_profile_pkey" PRIMARY KEY ("school_id", "user_id"),
    CONSTRAINT "hr_employee_profile_employee_code_key" UNIQUE ("school_id", "employee_code")
);

CREATE TABLE "hr"."shift" (
    "school_id" BIGINT NOT NULL,
    "shift_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "start_time" TIME NOT NULL,
    "end_time" TIME NOT NULL,
    "crosses_midnight" BOOLEAN DEFAULT false,
    "grace_minutes" INTEGER DEFAULT 10,
    "break_minutes" INTEGER,
    "half_day_after_minutes" INTEGER,
    "min_work_minutes" INTEGER,
    "overtime_after_minutes" INTEGER,
    "night_allowance" NUMERIC(14,2),
    "applies_to" TEXT DEFAULT 'ANY' CHECK ("applies_to" IN ('TEACHING', 'NON_TEACHING', 'SECURITY', 'HOSTEL', 'TRANSPORT', 'ANY')),
    CONSTRAINT "hr_shift_pkey" PRIMARY KEY ("shift_id"),
    CONSTRAINT "hr_shift_tenant_key" UNIQUE ("school_id", "shift_id"),
    CONSTRAINT "hr_shift_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "hr"."shift_assignment" (
    "school_id" BIGINT NOT NULL,
    "shift_assignment_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "shift_id" BIGINT NOT NULL,
    "weekdays" TEXT,
    "weekly_off" TEXT,
    "from_date" DATE NOT NULL,
    "to_date" DATE,
    "rotation" TEXT DEFAULT 'FIXED' CHECK ("rotation" IN ('FIXED', 'WEEKLY', 'FORTNIGHTLY')),
    CONSTRAINT "hr_shift_assignment_pkey" PRIMARY KEY ("shift_assignment_id"),
    CONSTRAINT "hr_shift_assignment_tenant_key" UNIQUE ("school_id", "shift_assignment_id")
);

CREATE TABLE "hr"."post" (
    "school_id" BIGINT NOT NULL,
    "post_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "post_type" TEXT NOT NULL CHECK ("post_type" IN ('GATE', 'PATROL', 'CCTV', 'HOSTEL_NIGHT', 'HOSTEL_DAY', 'MESS', 'EXAM', 'FRONT_DESK', 'LIBRARY_COUNTER', 'SICK_BAY', 'OTHER')),
    "location_id" BIGINT,
    "hostel_id" BIGINT,
    "required_per_shift" INTEGER DEFAULT 1,
    "device_id" BIGINT,
    CONSTRAINT "hr_post_pkey" PRIMARY KEY ("post_id"),
    CONSTRAINT "hr_post_tenant_key" UNIQUE ("school_id", "post_id"),
    CONSTRAINT "hr_post_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "hr"."roster_entry" (
    "school_id" BIGINT NOT NULL,
    "roster_entry_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "shift_id" BIGINT NOT NULL,
    "post_id" BIGINT,
    "duty_date" DATE NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'PLANNED' CHECK ("status" IN ('PLANNED', 'ON_DUTY', 'COMPLETED', 'ABSENT', 'SWAPPED', 'CANCELLED')),
    "swapped_with_user_id" BIGINT,
    "approved_by_user_id" BIGINT,
    "reported_at" TIMESTAMPTZ,
    CONSTRAINT "hr_roster_entry_pkey" PRIMARY KEY ("roster_entry_id"),
    CONSTRAINT "hr_roster_entry_tenant_key" UNIQUE ("school_id", "roster_entry_id")
);

-- ---------------------------------------------------------------------------
-- operations
-- ---------------------------------------------------------------------------

CREATE TABLE "operations"."attendance_punch" (
    "school_id" BIGINT NOT NULL,
    "punch_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "person_kind" TEXT NOT NULL CHECK ("person_kind" IN ('STUDENT', 'STAFF', 'VISITOR')),
    "person_id" BIGINT NOT NULL,
    "source" TEXT NOT NULL CHECK ("source" IN ('FINGERPRINT', 'FACE', 'RFID', 'QR', 'MANUAL', 'APP_GEOFENCE_OFF')),
    "direction" TEXT NOT NULL CHECK ("direction" IN ('IN', 'OUT')),
    "punched_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "device_id" BIGINT,
    "post_id" BIGINT,
    "marked_by_user_id" BIGINT,
    CONSTRAINT "operations_attendance_punch_pkey" PRIMARY KEY ("punch_id"),
    CONSTRAINT "operations_attendance_punch_tenant_key" UNIQUE ("school_id", "punch_id")
);

CREATE TABLE "operations"."daily_presence" (
    "school_id" BIGINT NOT NULL,
    "presence_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "person_kind" TEXT NOT NULL CHECK ("person_kind" IN ('STUDENT', 'STAFF')),
    "person_id" BIGINT NOT NULL,
    "presence_date" DATE NOT NULL,
    "shift_id" BIGINT,
    "roster_entry_id" BIGINT,
    "first_in_at" TIMESTAMPTZ,
    "last_out_at" TIMESTAMPTZ,
    "on_campus_minutes" INTEGER,
    "late_minutes" INTEGER,
    "early_leave_minutes" INTEGER,
    "overtime_minutes" INTEGER,
    "status" TEXT NOT NULL DEFAULT 'PRESENT' CHECK ("status" IN ('PRESENT', 'LATE', 'HALF_DAY', 'ABSENT', 'ON_LEAVE', 'ON_DUTY', 'WEEKLY_OFF', 'HOLIDAY', 'ON_OUTING')),
    "computed_by" TEXT DEFAULT 'SYSTEM' CHECK ("computed_by" IN ('SYSTEM', 'MANUAL')),
    "corrected_by_user_id" BIGINT,
    "recomputed_at" TIMESTAMPTZ,
    CONSTRAINT "operations_daily_presence_pkey" PRIMARY KEY ("presence_id"),
    CONSTRAINT "operations_daily_presence_tenant_key" UNIQUE ("school_id", "presence_id"),
    CONSTRAINT "operations_daily_presence_uq1" UNIQUE ("school_id", "person_kind", "person_id", "presence_date")
);

-- ---------------------------------------------------------------------------
-- hr
-- ---------------------------------------------------------------------------

CREATE TABLE "hr"."leave_type" (
    "school_id" BIGINT NOT NULL,
    "leave_type_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "annual_quota" NUMERIC(14,2),
    "carry_forward_max" NUMERIC(14,2),
    "is_paid" BOOLEAN DEFAULT true,
    "document_after_days" INTEGER,
    "applies_to" TEXT,
    CONSTRAINT "hr_leave_type_pkey" PRIMARY KEY ("leave_type_id"),
    CONSTRAINT "hr_leave_type_tenant_key" UNIQUE ("school_id", "leave_type_id"),
    CONSTRAINT "hr_leave_type_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "hr"."leave_balance" (
    "school_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "leave_type_id" BIGINT NOT NULL,
    "academic_year_id" BIGINT NOT NULL,
    "opening" NUMERIC(14,2) DEFAULT 0,
    "accrued" NUMERIC(14,2) DEFAULT 0,
    "used" NUMERIC(14,2) DEFAULT 0,
    "balance" NUMERIC(14,2) DEFAULT 0,
    CONSTRAINT "hr_leave_balance_pkey" PRIMARY KEY ("school_id", "user_id", "leave_type_id", "academic_year_id")
);

CREATE TABLE "hr"."leave_request" (
    "school_id" BIGINT NOT NULL,
    "leave_request_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "leave_type_id" BIGINT NOT NULL,
    "from_date" DATE NOT NULL,
    "to_date" DATE NOT NULL,
    "half_day" BOOLEAN DEFAULT false,
    "days" NUMERIC(14,2),
    "reason" TEXT,
    "document_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'PENDING' CHECK ("status" IN ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED')),
    "approver_user_id" BIGINT,
    "decided_at" TIMESTAMPTZ,
    CONSTRAINT "hr_leave_request_pkey" PRIMARY KEY ("leave_request_id"),
    CONSTRAINT "hr_leave_request_tenant_key" UNIQUE ("school_id", "leave_request_id")
);

CREATE TABLE "hr"."salary_component" (
    "school_id" BIGINT NOT NULL,
    "component_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "kind" TEXT NOT NULL CHECK ("kind" IN ('EARNING', 'DEDUCTION', 'EMPLOYER_CONTRIBUTION')),
    "calc" TEXT NOT NULL CHECK ("calc" IN ('FIXED', 'PERCENT_OF_BASIC', 'PER_DAY', 'PER_HOUR', 'FORMULA')),
    "formula" TEXT,
    CONSTRAINT "hr_salary_component_pkey" PRIMARY KEY ("component_id"),
    CONSTRAINT "hr_salary_component_tenant_key" UNIQUE ("school_id", "component_id"),
    CONSTRAINT "hr_salary_component_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "hr"."salary_structure" (
    "school_id" BIGINT NOT NULL,
    "structure_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "effective_from" DATE NOT NULL,
    "ctc_annual" NUMERIC(14,2),
    CONSTRAINT "hr_salary_structure_pkey" PRIMARY KEY ("structure_id"),
    CONSTRAINT "hr_salary_structure_tenant_key" UNIQUE ("school_id", "structure_id")
);

CREATE TABLE "hr"."salary_structure_line" (
    "school_id" BIGINT NOT NULL,
    "line_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "structure_id" BIGINT NOT NULL,
    "component_id" BIGINT NOT NULL,
    "amount_or_pct" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "hr_salary_structure_line_pkey" PRIMARY KEY ("line_id"),
    CONSTRAINT "hr_salary_structure_line_tenant_key" UNIQUE ("school_id", "line_id")
);

CREATE TABLE "hr"."payroll_run" (
    "school_id" BIGINT NOT NULL,
    "run_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "period" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'DRAFT' CHECK ("status" IN ('DRAFT', 'COMPUTED', 'APPROVED', 'PAID', 'LOCKED')),
    "computed_by_user_id" BIGINT,
    "approved_by_user_id" BIGINT,
    "paid_at" TIMESTAMPTZ,
    CONSTRAINT "hr_payroll_run_pkey" PRIMARY KEY ("run_id"),
    CONSTRAINT "hr_payroll_run_tenant_key" UNIQUE ("school_id", "run_id"),
    CONSTRAINT "hr_payroll_run_period_key" UNIQUE ("school_id", "period")
);

CREATE TABLE "hr"."payslip" (
    "school_id" BIGINT NOT NULL,
    "payslip_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "run_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "working_days" NUMERIC(14,2),
    "present_days" NUMERIC(14,2),
    "lop_days" NUMERIC(14,2),
    "overtime_minutes" INTEGER,
    "night_shifts" INTEGER,
    "gross" NUMERIC(14,2),
    "deductions" NUMERIC(14,2),
    "net" NUMERIC(14,2),
    "document_id" BIGINT,
    CONSTRAINT "hr_payslip_pkey" PRIMARY KEY ("payslip_id"),
    CONSTRAINT "hr_payslip_tenant_key" UNIQUE ("school_id", "payslip_id"),
    CONSTRAINT "hr_payslip_uq1" UNIQUE ("school_id", "run_id", "user_id")
);

CREATE TABLE "hr"."payslip_line" (
    "school_id" BIGINT NOT NULL,
    "line_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "payslip_id" BIGINT NOT NULL,
    "component_id" BIGINT NOT NULL,
    "amount" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "hr_payslip_line_pkey" PRIMARY KEY ("line_id"),
    CONSTRAINT "hr_payslip_line_tenant_key" UNIQUE ("school_id", "line_id")
);

-- ---------------------------------------------------------------------------
-- security
-- ---------------------------------------------------------------------------

CREATE TABLE "security"."checkpoint" (
    "school_id" BIGINT NOT NULL,
    "checkpoint_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "location_id" BIGINT,
    "tag_uid" TEXT,
    "lat" NUMERIC(14,2),
    "lng" NUMERIC(14,2),
    CONSTRAINT "security_checkpoint_pkey" PRIMARY KEY ("checkpoint_id"),
    CONSTRAINT "security_checkpoint_tenant_key" UNIQUE ("school_id", "checkpoint_id"),
    CONSTRAINT "security_checkpoint_code_key" UNIQUE ("school_id", "code"),
    CONSTRAINT "security_checkpoint_tag_uid_key" UNIQUE ("school_id", "tag_uid")
);

CREATE TABLE "security"."patrol_route" (
    "school_id" BIGINT NOT NULL,
    "route_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "post_id" BIGINT,
    "name" TEXT NOT NULL,
    "active_from" TIME,
    "active_to" TIME,
    "round_every_minutes" INTEGER,
    "max_round_minutes" INTEGER,
    CONSTRAINT "security_patrol_route_pkey" PRIMARY KEY ("route_id"),
    CONSTRAINT "security_patrol_route_tenant_key" UNIQUE ("school_id", "route_id")
);

CREATE TABLE "security"."route_checkpoint" (
    "school_id" BIGINT NOT NULL,
    "route_id" BIGINT NOT NULL,
    "checkpoint_id" BIGINT NOT NULL,
    "sequence" INTEGER NOT NULL,
    "photo_required" BOOLEAN DEFAULT false,
    CONSTRAINT "security_route_checkpoint_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "route_id", "checkpoint_id")
);

CREATE TABLE "security"."patrol_round" (
    "school_id" BIGINT NOT NULL,
    "round_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "route_id" BIGINT NOT NULL,
    "roster_entry_id" BIGINT,
    "guard_user_id" BIGINT,
    "due_at" TIMESTAMPTZ NOT NULL,
    "started_at" TIMESTAMPTZ,
    "completed_at" TIMESTAMPTZ,
    "missed_checkpoints" INTEGER,
    "status" TEXT NOT NULL DEFAULT 'DUE' CHECK ("status" IN ('DUE', 'IN_PROGRESS', 'COMPLETED', 'LATE', 'MISSED')),
    CONSTRAINT "security_patrol_round_pkey" PRIMARY KEY ("round_id"),
    CONSTRAINT "security_patrol_round_tenant_key" UNIQUE ("school_id", "round_id")
);

CREATE TABLE "security"."patrol_scan" (
    "school_id" BIGINT NOT NULL,
    "scan_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "round_id" BIGINT NOT NULL,
    "checkpoint_id" BIGINT NOT NULL,
    "scanned_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "lat" NUMERIC(14,2),
    "lng" NUMERIC(14,2),
    "method" TEXT CHECK ("method" IN ('NFC', 'QR', 'MANUAL_WITH_REASON')),
    "photo_url" TEXT,
    "note" TEXT,
    CONSTRAINT "security_patrol_scan_pkey" PRIMARY KEY ("scan_id"),
    CONSTRAINT "security_patrol_scan_tenant_key" UNIQUE ("school_id", "scan_id")
);

CREATE TABLE "security"."welfare_ping" (
    "school_id" BIGINT NOT NULL,
    "ping_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "roster_entry_id" BIGINT NOT NULL,
    "sent_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "responded_at" TIMESTAMPTZ,
    "status" TEXT CHECK ("status" IN ('OK', 'NO_RESPONSE', 'ESCALATED')),
    CONSTRAINT "security_welfare_ping_pkey" PRIMARY KEY ("ping_id"),
    CONSTRAINT "security_welfare_ping_tenant_key" UNIQUE ("school_id", "ping_id")
);

CREATE TABLE "security"."occurrence" (
    "school_id" BIGINT NOT NULL,
    "occurrence_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "occurrence_type" TEXT NOT NULL CHECK ("occurrence_type" IN ('INTRUDER', 'FIRE_ALARM', 'POWER_CUT', 'MEDICAL', 'SUSPICIOUS_VEHICLE', 'GATE_BREACH', 'ANIMAL', 'THEFT', 'OTHER')),
    "severity" TEXT NOT NULL CHECK ("severity" IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    "occurred_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "location_id" BIGINT,
    "checkpoint_id" BIGINT,
    "description" TEXT,
    "photo_urls" TEXT[],
    "reported_by_user_id" BIGINT,
    "roster_entry_id" BIGINT,
    "escalated_to_user_id" BIGINT,
    "ticket_id" BIGINT,
    "incident_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'OPEN' CHECK ("status" IN ('OPEN', 'ACKNOWLEDGED', 'RESOLVED')),
    CONSTRAINT "security_occurrence_pkey" PRIMARY KEY ("occurrence_id"),
    CONSTRAINT "security_occurrence_tenant_key" UNIQUE ("school_id", "occurrence_id")
);

CREATE TABLE "security"."shift_handover" (
    "school_id" BIGINT NOT NULL,
    "handover_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "post_id" BIGINT NOT NULL,
    "from_roster_entry_id" BIGINT,
    "to_roster_entry_id" BIGINT,
    "handed_over_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "notes" TEXT,
    "equipment" TEXT,
    "accepted" BOOLEAN DEFAULT false,
    CONSTRAINT "security_shift_handover_pkey" PRIMARY KEY ("handover_id"),
    CONSTRAINT "security_shift_handover_tenant_key" UNIQUE ("school_id", "handover_id")
);

CREATE TABLE "security"."key" (
    "school_id" BIGINT NOT NULL,
    "key_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "location_id" BIGINT,
    "is_master" BOOLEAN DEFAULT false,
    CONSTRAINT "security_key_pkey" PRIMARY KEY ("key_id"),
    CONSTRAINT "security_key_tenant_key" UNIQUE ("school_id", "key_id"),
    CONSTRAINT "security_key_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "security"."key_movement" (
    "school_id" BIGINT NOT NULL,
    "key_movement_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "key_id" BIGINT NOT NULL,
    "issued_to_user_id" BIGINT,
    "issued_by_user_id" BIGINT,
    "issued_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "due_back_at" TIMESTAMPTZ,
    "returned_at" TIMESTAMPTZ,
    CONSTRAINT "security_key_movement_pkey" PRIMARY KEY ("key_movement_id"),
    CONSTRAINT "security_key_movement_tenant_key" UNIQUE ("school_id", "key_movement_id")
);

CREATE TABLE "security"."vehicle_entry" (
    "school_id" BIGINT NOT NULL,
    "vehicle_entry_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "post_id" BIGINT,
    "vehicle_number" TEXT NOT NULL,
    "purpose" TEXT CHECK ("purpose" IN ('VENDOR', 'PARENT', 'STAFF', 'DELIVERY', 'OTHER')),
    "visit_id" BIGINT,
    "in_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "out_at" TIMESTAMPTZ,
    "logged_by_user_id" BIGINT,
    CONSTRAINT "security_vehicle_entry_pkey" PRIMARY KEY ("vehicle_entry_id"),
    CONSTRAINT "security_vehicle_entry_tenant_key" UNIQUE ("school_id", "vehicle_entry_id")
);

-- ---------------------------------------------------------------------------
-- transport
-- ---------------------------------------------------------------------------

CREATE TABLE "transport"."vehicle" (
    "school_id" BIGINT NOT NULL,
    "vehicle_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "registration_number" TEXT NOT NULL,
    "vehicle_type" TEXT CHECK ("vehicle_type" IN ('BUS', 'VAN', 'CAR')),
    "capacity" INTEGER,
    "gps_device_id" TEXT,
    "insurance_valid_till" DATE,
    "fitness_valid_till" DATE,
    "permit_valid_till" DATE,
    "puc_valid_till" DATE,
    "asset_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'IN_REPAIR', 'RETIRED')),
    CONSTRAINT "transport_vehicle_pkey" PRIMARY KEY ("vehicle_id"),
    CONSTRAINT "transport_vehicle_tenant_key" UNIQUE ("school_id", "vehicle_id"),
    CONSTRAINT "transport_vehicle_registration_number_key" UNIQUE ("school_id", "registration_number")
);

CREATE TABLE "transport"."route" (
    "school_id" BIGINT NOT NULL,
    "route_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "shift" TEXT CHECK ("shift" IN ('MORNING', 'AFTERNOON', 'BOTH')),
    "vehicle_id" BIGINT,
    "driver_user_id" BIGINT,
    "attendant_user_id" BIGINT,
    CONSTRAINT "transport_route_pkey" PRIMARY KEY ("route_id"),
    CONSTRAINT "transport_route_tenant_key" UNIQUE ("school_id", "route_id"),
    CONSTRAINT "transport_route_code_key" UNIQUE ("school_id", "code")
);

CREATE TABLE "transport"."stop" (
    "school_id" BIGINT NOT NULL,
    "stop_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "route_id" BIGINT NOT NULL,
    "name" TEXT NOT NULL,
    "lat" NUMERIC(14,2),
    "lng" NUMERIC(14,2),
    "sequence" INTEGER,
    "pickup_time" TIME,
    "drop_time" TIME,
    "fee_structure_id" BIGINT,
    CONSTRAINT "transport_stop_pkey" PRIMARY KEY ("stop_id"),
    CONSTRAINT "transport_stop_tenant_key" UNIQUE ("school_id", "stop_id")
);

CREATE TABLE "transport"."student_route" (
    "school_id" BIGINT NOT NULL,
    "student_id" BIGINT NOT NULL,
    "route_id" BIGINT NOT NULL,
    "pickup_stop_id" BIGINT,
    "drop_stop_id" BIGINT,
    "from_date" DATE NOT NULL,
    "to_date" DATE,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE', 'ENDED')),
    CONSTRAINT "transport_student_route_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "student_id", "route_id", "from_date")
);

CREATE TABLE "transport"."trip" (
    "school_id" BIGINT NOT NULL,
    "trip_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "route_id" BIGINT NOT NULL,
    "vehicle_id" BIGINT,
    "driver_user_id" BIGINT,
    "roster_entry_id" BIGINT,
    "trip_date" DATE NOT NULL,
    "direction" TEXT NOT NULL CHECK ("direction" IN ('PICKUP', 'DROP', 'HOSTEL_STATION_DROP')),
    "group_id" BIGINT,
    "started_at" TIMESTAMPTZ,
    "ended_at" TIMESTAMPTZ,
    "status" TEXT NOT NULL DEFAULT 'PLANNED' CHECK ("status" IN ('PLANNED', 'RUNNING', 'COMPLETED', 'CANCELLED')),
    CONSTRAINT "transport_trip_pkey" PRIMARY KEY ("trip_id"),
    CONSTRAINT "transport_trip_tenant_key" UNIQUE ("school_id", "trip_id")
);

CREATE TABLE "transport"."trip_location" (
    "school_id" BIGINT NOT NULL,
    "trip_id" BIGINT NOT NULL,
    "recorded_at" TIMESTAMPTZ NOT NULL,
    "lat" NUMERIC(14,2) NOT NULL,
    "lng" NUMERIC(14,2) NOT NULL,
    "speed_kmph" NUMERIC(14,2),
    CONSTRAINT "transport_trip_location_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "trip_id", "recorded_at")
);

CREATE TABLE "transport"."boarding" (
    "school_id" BIGINT NOT NULL,
    "boarding_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "trip_id" BIGINT NOT NULL,
    "student_id" BIGINT NOT NULL,
    "stop_id" BIGINT,
    "event" TEXT NOT NULL CHECK ("event" IN ('BOARDED', 'ALIGHTED', 'NO_SHOW')),
    "event_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "source" TEXT CHECK ("source" IN ('RFID', 'QR', 'MANUAL')),
    "marked_by_user_id" BIGINT,
    CONSTRAINT "transport_boarding_pkey" PRIMARY KEY ("boarding_id"),
    CONSTRAINT "transport_boarding_tenant_key" UNIQUE ("school_id", "boarding_id")
);

CREATE TABLE "transport"."fuel_log" (
    "school_id" BIGINT NOT NULL,
    "fuel_log_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "vehicle_id" BIGINT NOT NULL,
    "filled_on" DATE NOT NULL,
    "litres" NUMERIC(14,2),
    "amount" NUMERIC(14,2),
    "odometer_km" INTEGER,
    "expense_id" BIGINT,
    CONSTRAINT "transport_fuel_log_pkey" PRIMARY KEY ("fuel_log_id"),
    CONSTRAINT "transport_fuel_log_tenant_key" UNIQUE ("school_id", "fuel_log_id")
);

-- ---------------------------------------------------------------------------
-- communication
-- ---------------------------------------------------------------------------

CREATE TABLE "communication"."conversation" (
    "school_id" BIGINT NOT NULL,
    "conversation_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "kind" TEXT NOT NULL CHECK ("kind" IN ('PARENT_TEACHER', 'CLASS_GROUP', 'HOSTEL_GROUP', 'HELPDESK')),
    "student_id" BIGINT,
    "class_section_id" BIGINT,
    "hostel_id" BIGINT,
    "created_by_user_id" BIGINT,
    "parents_can_reply" BOOLEAN DEFAULT true,
    "is_locked" BOOLEAN DEFAULT false,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "communication_conversation_pkey" PRIMARY KEY ("conversation_id"),
    CONSTRAINT "communication_conversation_tenant_key" UNIQUE ("school_id", "conversation_id")
);

CREATE TABLE "communication"."conversation_member" (
    "school_id" BIGINT NOT NULL,
    "conversation_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "member_role" TEXT NOT NULL CHECK ("member_role" IN ('STAFF', 'PARENT', 'STUDENT', 'MODERATOR')),
    "last_read_at" TIMESTAMPTZ,
    "muted" BOOLEAN DEFAULT false,
    CONSTRAINT "communication_conversation_member_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "conversation_id", "user_id")
);

CREATE TABLE "communication"."message" (
    "school_id" BIGINT NOT NULL,
    "message_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "conversation_id" BIGINT NOT NULL,
    "sender_user_id" BIGINT NOT NULL,
    "body" TEXT,
    "attachment_urls" TEXT[],
    "sent_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "deleted_at" TIMESTAMPTZ,
    "flagged" BOOLEAN DEFAULT false,
    CONSTRAINT "communication_message_pkey" PRIMARY KEY ("message_id"),
    CONSTRAINT "communication_message_tenant_key" UNIQUE ("school_id", "message_id")
);

CREATE TABLE "communication"."messaging_policy" (
    "school_id" BIGINT NOT NULL,
    "parent_can_start_chat" BOOLEAN DEFAULT true,
    "office_hours_start" TIME,
    "office_hours_end" TIME,
    "show_staff_phone" BOOLEAN DEFAULT false,
    "retention_days" INTEGER,
    CONSTRAINT "communication_messaging_policy_pkey" PRIMARY KEY ("school_id")
);

CREATE TABLE "communication"."template" (  -- school_id NULL = platform default row
    "school_id" BIGINT,
    "template_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "event_code" TEXT NOT NULL CHECK ("event_code" IN ('FEE_DUE', 'ABSENT', 'LATE_ARRIVAL', 'OUTING_APPROVED', 'LATE_RETURN', 'PHONE_RELEASED', 'PHONE_DEPOSITED', 'MISSING_AT_ROLL_CALL', 'BUS_NEAR')),
    "channel" TEXT NOT NULL CHECK ("channel" IN ('WHATSAPP', 'EMAIL', 'PUSH')),
    "language" TEXT NOT NULL DEFAULT 'en',
    "whatsapp_template_name" TEXT,
    "body" TEXT NOT NULL,
    CONSTRAINT "communication_template_pkey" PRIMARY KEY ("template_id")
);

CREATE TABLE "communication"."poll" (
    "school_id" BIGINT NOT NULL,
    "poll_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "notification_id" BIGINT,
    "question" TEXT NOT NULL,
    "options" JSONB NOT NULL,
    "is_anonymous" BOOLEAN DEFAULT false,
    "one_per_child" BOOLEAN DEFAULT false,
    "closes_at" TIMESTAMPTZ,
    CONSTRAINT "communication_poll_pkey" PRIMARY KEY ("poll_id"),
    CONSTRAINT "communication_poll_tenant_key" UNIQUE ("school_id", "poll_id")
);

CREATE TABLE "communication"."poll_response" (
    "school_id" BIGINT NOT NULL,
    "poll_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "student_id" BIGINT,
    "option_key" TEXT NOT NULL,
    "responded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "communication_poll_response_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "poll_id", "user_id", "student_id")
);

CREATE TABLE "communication"."ptm_session" (
    "school_id" BIGINT NOT NULL,
    "ptm_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "event_id" BIGINT,
    "class_section_id" BIGINT,
    "slot_minutes" INTEGER,
    "mode" TEXT CHECK ("mode" IN ('IN_PERSON', 'VIDEO')),
    CONSTRAINT "communication_ptm_session_pkey" PRIMARY KEY ("ptm_id"),
    CONSTRAINT "communication_ptm_session_tenant_key" UNIQUE ("school_id", "ptm_id")
);

CREATE TABLE "communication"."ptm_slot" (
    "school_id" BIGINT NOT NULL,
    "slot_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ptm_id" BIGINT NOT NULL,
    "teacher_user_id" BIGINT NOT NULL,
    "start_at" TIMESTAMPTZ NOT NULL,
    "booked_by_user_id" BIGINT,
    "student_id" BIGINT,
    "status" TEXT NOT NULL DEFAULT 'OPEN' CHECK ("status" IN ('OPEN', 'BOOKED', 'DONE', 'NO_SHOW', 'CANCELLED')),
    "teacher_notes" TEXT,
    CONSTRAINT "communication_ptm_slot_pkey" PRIMARY KEY ("slot_id"),
    CONSTRAINT "communication_ptm_slot_tenant_key" UNIQUE ("school_id", "slot_id")
);

