    "verified_by_user_id" BIGINT,
    CONSTRAINT "frontoffice_gate_pass_pkey" PRIMARY KEY ("gate_pass_id"),
    CONSTRAINT "frontoffice_gate_pass_tenant_key" UNIQUE ("school_id", "gate_pass_id")
);

CREATE TABLE "frontoffice"."parcel" (
    "school_id" BIGINT NOT NULL,
