    "handed_over_at" TIMESTAMPTZ,
    "handed_over_by_user_id" BIGINT,
    CONSTRAINT "frontoffice_parcel_pkey" PRIMARY KEY ("parcel_id"),
    CONSTRAINT "frontoffice_parcel_tenant_key" UNIQUE ("school_id", "parcel_id")
