-- ---------------------------------------------------------------------------
-- facility
-- ---------------------------------------------------------------------------

CREATE TABLE "facility"."ticket" (
    "school_id" BIGINT NOT NULL,
    "ticket_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "category" TEXT NOT NULL CHECK ("category" IN ('ELECTRICAL', 'PLUMBING', 'CARPENTRY', 'CLEANING', 'IT', 'MESS', 'SECURITY', 'ROOMMATE', 'OTHER')),
    "location_id" BIGINT,
    "room_id" BIGINT,
    "asset_id" BIGINT,
    "raised_by_user_id" BIGINT,
