    "description" TEXT NOT NULL,
    "photo_urls" TEXT[],
    "priority" TEXT DEFAULT 'MEDIUM' CHECK ("priority" IN ('LOW', 'MEDIUM', 'HIGH', 'URGENT')),
    "assigned_to_user_id" BIGINT,
    "sla_due_at" TIMESTAMPTZ,
    "status" TEXT NOT NULL DEFAULT 'OPEN' CHECK ("status" IN ('OPEN', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED', 'CLOSED', 'REOPENED')),
    "resolved_at" TIMESTAMPTZ,
    "resolution_note" TEXT,
    "expense_id" BIGINT,
    CONSTRAINT "facility_ticket_pkey" PRIMARY KEY ("ticket_id"),
    CONSTRAINT "facility_ticket_tenant_key" UNIQUE ("school_id", "ticket_id")
);

