    "given_on" DATE,
    "document_id" BIGINT,
    CONSTRAINT "wellbeing_vaccination_pkey" PRIMARY KEY ("vaccination_id"),
    CONSTRAINT "wellbeing_vaccination_tenant_key" UNIQUE ("school_id", "vaccination_id")
);

CREATE TABLE "wellbeing"."health_checkup" (
    "school_id" BIGINT NOT NULL,
