    CONSTRAINT "discipline_incident_pkey" PRIMARY KEY ("incident_id"),
    CONSTRAINT "discipline_incident_tenant_key" UNIQUE ("school_id", "incident_id")
);

CREATE TABLE "discipline"."incident_student" (
    "school_id" BIGINT NOT NULL,
    "incident_id" BIGINT NOT NULL,
    "student_id" BIGINT NOT NULL,
    "involvement" TEXT NOT NULL CHECK ("involvement" IN ('PRIMARY', 'INVOLVED', 'WITNESS', 'AFFECTED')),
    CONSTRAINT "discipline_incident_student_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "incident_id", "student_id")
