    "from_date" DATE,
    "to_date" DATE,
    "fine_fee_id" BIGINT,
    "decided_by_user_id" BIGINT,
    "parent_notified_at" TIMESTAMPTZ,
    CONSTRAINT "discipline_action_pkey" PRIMARY KEY ("action_id"),
