    "issued_on" DATE,
    "issued_by_user_id" BIGINT,
    "document_id" BIGINT,
    "revoked_at" TIMESTAMPTZ,
    CONSTRAINT "records_certificate_pkey" PRIMARY KEY ("certificate_id"),
    CONSTRAINT "records_certificate_tenant_key" UNIQUE ("school_id", "certificate_id"),
