    "stage" TEXT NOT NULL CHECK ("stage" IN ('APPLIED', 'SCREENED', 'DEMO_CLASS', 'INTERVIEW', 'OFFERED', 'JOINED', 'REJECTED')),
    CONSTRAINT "hr_candidate_pkey" PRIMARY KEY ("candidate_id"),
    CONSTRAINT "hr_candidate_tenant_key" UNIQUE ("school_id", "candidate_id")
);

-- ---------------------------------------------------------------------------
-- communication
-- ---------------------------------------------------------------------------

CREATE TABLE "communication"."news_post" (  -- addition beyond ER v5
    "school_id" BIGINT NOT NULL,
    "post_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "author_user_id" BIGINT NOT NULL,
    "title" TEXT,
    "body" TEXT,
    "audience_type" TEXT NOT NULL DEFAULT 'ALL' CHECK ("audience_type" IN ('ALL', 'SECTION', 'PROGRAM', 'HOSTEL', 'STAFF')),
    "class_section_id" BIGINT,
    "program_id" BIGINT,
    "hostel_id" BIGINT,
    "is_pinned" BOOLEAN DEFAULT false,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "expires_at" TIMESTAMPTZ NOT NULL DEFAULT (now() + INTERVAL '30 days'),
    "deleted_at" TIMESTAMPTZ,
    CONSTRAINT "communication_news_post_pkey" PRIMARY KEY ("post_id"),
    CONSTRAINT "communication_news_post_tenant_key" UNIQUE ("school_id", "post_id")
);

CREATE TABLE "communication"."news_media" (  -- addition beyond ER v5
    "school_id" BIGINT NOT NULL,
    "media_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "post_id" BIGINT NOT NULL,
    "provider" TEXT NOT NULL CHECK ("provider" IN ('DRIVE', 'DROPBOX', 'LOCAL')),
    "file_id" TEXT NOT NULL,
    "mime_type" TEXT NOT NULL,
    "size_bytes" BIGINT NOT NULL,
    "width" INTEGER,
    "height" INTEGER,
    "duration_seconds" INTEGER,
    "sort_order" INTEGER DEFAULT 0,
    "purged_at" TIMESTAMPTZ,
    CONSTRAINT "communication_news_media_pkey" PRIMARY KEY ("media_id"),
    CONSTRAINT "communication_news_media_tenant_key" UNIQUE ("school_id", "media_id")
);

CREATE TABLE "communication"."news_reaction" (  -- addition beyond ER v5
    "school_id" BIGINT NOT NULL,
    "post_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "reaction" TEXT NOT NULL CHECK ("reaction" IN ('LIKE', 'LOVE', 'CLAP', 'CELEBRATE')),
    "reacted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "communication_news_reaction_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "post_id", "user_id")
);

-- ---------------------------------------------------------------------------
-- platform
-- ---------------------------------------------------------------------------

CREATE TABLE "platform"."idempotency_key" (  -- addition beyond ER v5
    "school_id" BIGINT NOT NULL,
    "idempotency_key" TEXT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "request_hash" TEXT NOT NULL,
    "response_status" INTEGER,
    "response_body" JSONB,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "platform_idempotency_key_key1" UNIQUE NULLS NOT DISTINCT ("school_id", "idempotency_key")
);

CREATE TABLE "platform"."outbox_event" (  -- addition beyond ER v5
    "school_id" BIGINT NOT NULL,
    "event_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "event_type" TEXT NOT NULL,
    "channel" TEXT NOT NULL CHECK ("channel" IN ('PUSH', 'WHATSAPP', 'EMAIL', 'INTERNAL')),
    "recipient_user_id" BIGINT,
    "payload" JSONB NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'PENDING' CHECK ("status" IN ('PENDING', 'SENT', 'FAILED', 'DEAD')),
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "next_attempt_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "sent_at" TIMESTAMPTZ,
    "last_error" TEXT,
    CONSTRAINT "platform_outbox_event_pkey" PRIMARY KEY ("event_id"),
    CONSTRAINT "platform_outbox_event_tenant_key" UNIQUE ("school_id", "event_id")
);

CREATE TABLE "platform"."flow_definition" (  -- addition beyond ER v5  -- school_id NULL = platform default row
    "school_id" BIGINT,
    "flow_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "flow_code" TEXT NOT NULL,
    "version" INTEGER NOT NULL DEFAULT 1,
    "name" TEXT NOT NULL,
    "definition" JSONB NOT NULL,
    "is_active" BOOLEAN DEFAULT true,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "platform_flow_definition_pkey" PRIMARY KEY ("flow_id"),
    CONSTRAINT "platform_flow_definition_uq1" UNIQUE ("school_id", "flow_code", "version")
);

CREATE TABLE "platform"."flow_instance" (  -- addition beyond ER v5
    "school_id" BIGINT NOT NULL,
    "instance_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "flow_id" BIGINT NOT NULL,
    "ref_kind" TEXT NOT NULL,
    "ref_id" BIGINT NOT NULL,
    "current_step" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'OPEN' CHECK ("status" IN ('OPEN', 'APPROVED', 'REJECTED', 'CANCELLED', 'SENT_BACK')),
    "submitted_by_user_id" BIGINT,
    "amount" NUMERIC(14,2),
    "due_by" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "closed_at" TIMESTAMPTZ,
    CONSTRAINT "platform_flow_instance_pkey" PRIMARY KEY ("instance_id"),
    CONSTRAINT "platform_flow_instance_tenant_key" UNIQUE ("school_id", "instance_id")
);

CREATE TABLE "platform"."flow_transition_log" (  -- addition beyond ER v5
    "school_id" BIGINT NOT NULL,
    "log_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "instance_id" BIGINT NOT NULL,
    "from_step" TEXT,
    "to_step" TEXT NOT NULL,
    "action" TEXT NOT NULL CHECK ("action" IN ('SUBMIT', 'APPROVE', 'REJECT', 'SEND_BACK', 'ESCALATE', 'CANCEL', 'AUTO')),
    "actor_user_id" BIGINT,
    "actor_role_code" TEXT,
    "note" TEXT,
    "occurred_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "platform_flow_transition_log_pkey" PRIMARY KEY ("log_id"),
    CONSTRAINT "platform_flow_transition_log_tenant_key" UNIQUE ("school_id", "log_id")
);
